'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const chapterNames=['保守的革命者','革命時機已經成熟','求學日本','動盪與背叛','走近共產國際','孫中山逝世前後','北伐','上海事變','蔣氏再婚','蔣“統一”中國','失去的革命','命運自定','毛澤東的崛起','日本和西安事變','日本全面侵華','日本陷入困境','蔣介石和他的同盟者','戰爭結束','馬歇爾使命的失敗','蔣介石引退','蔣介石失去大陸','避難之地','最後二十年','對蔣介石的評價'];
const sourceBook='https://www.sanmin.com.tw/product/index/004594230';
const photos={young:{title:'1907 / 早年肖像',description:'檔案標註爲 1907 年。攝影者不詳；原始來源爲國史館，轉載於 Wikimedia Commons。',file:'Chiang_Kaishek_in_Baoding_Military_Academy.jpg'},whampoa:{title:'1924 / 黃埔軍校開學典禮',description:'1924 年 6 月 16 日，孫中山在黃埔軍校開學典禮上講話，蔣介石在臺上。攝影者不詳。',file:'Whampoa3.jpg'},cairo:{title:'1943 / 開羅會議',description:'1943 年 11 月 25 日，蔣介石、羅斯福與丘吉爾合影。影像來自羅斯福總統圖書館檔案。',file:'Cairo_conference.jpg'},chongqing:{title:'1945 / 重慶',description:'1945 年 9 月，毛澤東與蔣介石在重慶舉杯。攝影者不詳。照片並不能概括雙方政治分歧或談判的結果。',file:'1945_Mao_and_Chiang.jpg'},late:{title:'1966 / 臺北閱兵現場',description:'1966 年 10 月 10 日的閱兵現場。攝影：Les Duffin，當時駐臺灣的美國軍官。',file:'DoubleTenDayParadeOctober101966.jpg'},wedding:{title:'1927 / 蔣介石與宋美齡婚禮',description:'1927 年婚禮合影。攝影：中華照相館。',file:'1927_Chiang_Soong_wedding_photo1.jpg'},family:{title:'1940 年代 / 家庭合影',description:'蔣介石、宋美齡與蔣經國、蔣緯國的合影。檔案僅標註 1940 年代，攝影者不詳；不推定更精確日期。',file:'Chiang_Soong_and_two_sons.jpg'},son:{title:'1948 / 蔣介石與蔣經國',description:'檔案文件標題標註爲 1948 年的父子合影。攝影者不詳。',file:'Chiang_Kai-shek_and_Chiang_Ching-Kuo_in_1948.jpg'}};
Object.values(photos).forEach(p=>p.source='https://commons.wikimedia.org/wiki/File:'+p.file);
const lives={1907:{photo:'young',label:'FIG. 01 / EARLY YEARS',place:'中國 / 早年',title:'還未成爲|歷史人物。',description:'這張標註爲 1907 年的照片，留下蔣介石早年的面貌。此後，求學、軍事訓練與革命活動，將逐漸改變他的道路。',chapter:3,question:'青年時代的經歷，怎樣影響此後的信念與行動？',background:'本書第三章以「求學日本」爲題，爲讀者提供理解早年經歷的切口。把青年時期的軍事學習，與後來加入革命活動的過程聯繫起來，可以觀察一個人的道路如何逐步成形。照片留下的是面貌；關於性格和信念的解釋，還需要藉助傳記敘述與其他史料。'},1924:{photo:'whampoa',label:'FIG. 02 / WHAMPOA',place:'廣州 / 黃埔',title:'從軍事教育，|走向政治舞臺。',description:'1924 年 6 月，黃埔軍校舉行開學典禮，孫中山講話，蔣介石在臺上。軍校既是軍事訓練的場所，也連接着當時的革命與政治組織。',chapter:6,question:'孫中山的影響與黃埔經歷，如何進入蔣介石的政治道路？',background:'黃埔軍校的建立，是國民革命發展中的重要節點。蔣介石擔任校長，軍事教育與政治組織在這裏交匯。閱讀「走近共產國際」「孫中山逝世前後」與「北伐」，可將人物經歷放回合作、競爭與組織變動的背景中。'},1943:{photo:'cairo',label:'FIG. 03 / CAIRO',place:'埃及 / 開羅',title:'戰爭中的同盟。|外交中的選擇。',description:'1943 年 11 月，蔣介石、羅斯福與丘吉爾在開羅會面。中國的抗戰與盟國的戰略安排，出現在同一個外交現場。',chapter:17,question:'共同的戰爭目標之下，各方如何協調自己的利益與判斷？',background:'開羅會議把中國、美國與英國領導人帶到一起。美國國務院公開的會議文獻記錄了軍事與政治議題，也讓讀者有機會對照傳記中的解釋。人物合影呈現合作的公開形象，會議記錄則有助於瞭解議程、立場與談判。'},1945:{photo:'chongqing',label:'FIG. 04 / CHONGQING',place:'中國 / 重慶',title:'戰爭結束，|分歧仍在。',description:'1945 年 9 月，毛澤東與蔣介石在重慶舉杯。抗戰勝利之後，和平、政治安排與新的衝突，構成了傳記中的另一段轉折。',chapter:18,question:'戰爭結束，爲什麼沒有讓政治分歧隨之結束？',background:'抗戰結束後，國共之間圍繞政治與軍事安排展開談判。照片中的舉杯，是歷史的一瞬，不能替代對後續過程的理解。從「戰爭結束」到「馬歇爾使命的失敗」，本書的章節把視線轉向戰後秩序與內戰前景。'},1966:{photo:'late',label:'FIG. 05 / LATER YEARS',place:'臺灣 / 臺北',title:'轉折以後，|人生仍在繼續。',description:'1966 年的閱兵影像，留下蔣介石晚年的公開形象。與早年肖像對照，可以看到同一個人處於不同歷史環境中的變化。',chapter:23,question:'理解晚年，怎樣同時看待個人經歷與當時的政治環境？',background:'本書在「蔣介石失去大陸」之後，以「避難之地」與「最後二十年」繼續敘述，最後進入「對蔣介石的評價」。晚年章節提醒讀者，傳記並不止於一個決定性轉折；遷移後的政治環境、個人記憶與歷史評價，仍是理解人物的部分。'}};
const relations={wedding:{date:'1927 / WEDDING PORTRAIT',title:'一段婚姻，也是一條閱讀線索。',text:'1927 年，蔣介石與宋美齡結婚。本書以「蔣氏再婚」設章，提示讀者從婚姻與家庭關係進入人物經歷。此後，宋美齡也出現在國際外交的現場。'},family:{date:'1940s / FAMILY FRAME',title:'政治人物，也有家庭中的身份。',text:'這張家庭合影將蔣介石、宋美齡與蔣經國、蔣緯國放在同一個畫面中。家庭關係爲個人傳記提供了不同於公開演說和軍事行動的觀察尺度。照片只能提供片段，親密關係的理解仍需結合可靠史料。'},son:{date:'1948 / FATHER & SON',title:'一張父子合影，留下兩代人的交點。',text:'檔案標題將這張蔣介石與蔣經國的照片標註爲 1948 年。從家庭身份到公共角色，父子經歷相互連接，也各自受到時代處境的影響。閱讀晚年章節時，可以將個人關係與政治環境並置思考。'}};
let currentYear='1907',sound=false,audioContext;
function beep(){if(!sound)return;audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='triangle';o.frequency.setValueAtTime(520,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(170,audioContext.currentTime+.065);g.gain.setValueAtTime(.025,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.09);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.1)}
$('#sound-toggle').onclick=()=>{sound=!sound;$('#sound-toggle').setAttribute('aria-pressed',String(sound));$('#sound-toggle').setAttribute('aria-label',`聲音：${sound?'開啓':'關閉'}，點擊${sound?'關閉':'開啓'}交互音效`);$('#sound-toggle small').textContent=sound?'聲音開':'聲音關';beep()};
const focusMemory=new Map();
function openDialog(id){const d=$('#'+id);focusMemory.set(d,document.activeElement);d.showModal();document.body.style.overflow='hidden';d.scrollTop=0;beep();if(id==='command-menu')$('#menu-toggle').setAttribute('aria-expanded','true')}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{document.body.style.overflow='';$('#menu-toggle').setAttribute('aria-expanded','false');focusMemory.get(d)?.focus({preventScroll:true})});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#menu-toggle').onclick=()=>openDialog('command-menu');
const menuLinks=$$('[data-menu]');function highlightMenu(a){menuLinks.forEach(x=>x.classList.toggle('active',x===a));$('.menu-art>strong').textContent=a.dataset.menu}
menuLinks.forEach(a=>{a.onmouseenter=()=>highlightMenu(a);a.onfocus=()=>highlightMenu(a);a.onclick=()=>{$('#command-menu').close();beep()}});highlightMenu(menuLinks[0]);$('#command-menu').addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();let i=menuLinks.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?menuLinks.length-1:(i+(e.key==='ArrowDown'?1:-1)+menuLinks.length)%menuLinks.length;menuLinks[i].focus()});
function switchAnimation(panel,change){panel.classList.remove('changing');change();if(!reduced.matches){void panel.offsetWidth;panel.classList.add('changing');setTimeout(()=>panel.classList.remove('changing'),500)}beep()}
function setupTabs(selector,activate){const tabs=$$(selector);tabs.forEach((b,i)=>{b.onclick=()=>activate(b);b.onkeydown=e=>{const delta={ArrowRight:1,ArrowDown:1,ArrowLeft:-1,ArrowUp:-1}[e.key];if(delta===undefined&&!['Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+delta+tabs.length)%tabs.length;tabs[next].focus();activate(tabs[next])}})}
function setTab(selector,button){$$(selector).forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1})}
setupTabs('[data-year]',b=>{currentYear=b.dataset.year;const s=lives[currentYear],p=photos[s.photo];setTab('[data-year]',b);switchAnimation($('#life-panel'),()=>{$('#life-panel').setAttribute('aria-labelledby',b.id);$('.life-year').textContent=currentYear;$('.life-location').textContent=s.place;$('.life-story h3').replaceChildren(document.createTextNode(s.title.split('|')[0]),document.createElement('br'),Object.assign(document.createElement('b'),{textContent:s.title.split('|')[1]}));$('#life-description').textContent=s.description;$('#life-chapter').textContent=`第 ${s.chapter} 章 · ${chapterNames[s.chapter-1]}`;$('#life-question').textContent=s.question;$('#life-image').src=`assets/${s.photo}.webp`;$('#life-image').alt=p.title;$('.life-photo').dataset.photo=s.photo;$('.life-photo').setAttribute('aria-label','放大查看'+p.title);$('.life-photo-label').textContent=s.label;$('#life-source').href=p.source})});
setupTabs('[data-relation]',b=>{const key=b.dataset.relation,s=relations[key],p=photos[key];setTab('[data-relation]',b);switchAnimation($('#relation-panel'),()=>{$('#relation-panel').setAttribute('aria-labelledby',b.id);$('#relation-image').src=`assets/${key}.webp`;$('#relation-image').alt=p.title;$('.relation-photo').dataset.photo=key;$('.relation-photo').setAttribute('aria-label','放大查看'+p.title);$('#relation-date').textContent=s.date;$('.relation-caption h3').textContent=s.title;$('.relation-caption p').textContent=s.text;$('#relation-source').href=p.source})});
const people={chiang:['01 / CHIANG KAI-SHEK','蔣介石','代表中國參與開羅會議，與盟國領導人商議戰爭與戰後安排。個人傳記在這裏進入世界外交的現場。'],roosevelt:['02 / FRANKLIN D. ROOSEVELT','富蘭克林·羅斯福','時任美國總統。開羅會議是其與盟國領導人協調戰爭戰略和戰後安排的一部分；會議之後，他前往德黑蘭與丘吉爾、斯大林會面。'],churchill:['03 / WINSTON CHURCHILL','溫斯頓·丘吉爾','時任英國首相。開羅會議中的盟國合作，涉及戰爭目標與不同的戰略關注；公開文獻提供了比合影更豐富的會議背景。']};
$$('[data-person]').forEach(b=>{b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.onclick=()=>{const p=people[b.dataset.person];$$('[data-person]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const d=$('#world-person');$('.mini-label',d).textContent=p[0];$('h3',d).textContent=p[1];$('p',d).textContent=p[2];if(!reduced.matches)d.animate([{transform:'translateX(-15px)',opacity:.35},{transform:'translateX(0)',opacity:1}],{duration:250,easing:'cubic-bezier(.2,.8,.2,1)'});beep()}});
$$('[data-photo]').forEach(b=>b.onclick=()=>{const key=b.dataset.photo,p=photos[key];$('#photo-full').src=`assets/${key}.webp`;$('#photo-full').alt=p.title;$('#photo-title').textContent=p.title;$('#photo-description').textContent=p.description;$('#photo-source').href=p.source;openDialog('photo-viewer')});
const link=(href,label)=>`<a href="${href}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const photoBlock=key=>`<figure><img class="reader-photo" src="assets/${key}.webp" alt="${photos[key].title}"><figcaption>${photos[key].description} ${link(photos[key].source,'影像來源')}</figcaption></figure>`;
const chapters=ns=>'<ol class="contents-list">'+ns.map(n=>`<li value="${n}">${chapterNames[n-1]}</li>`).join('')+'</ol>';
function readerData(key){if(key==='life'){const s=lives[currentYear];return ['HISTORICAL CONTEXT / '+currentYear,s.title.replace('|',''),photoBlock(s.photo)+`<p>${s.background}</p><h3>繼續閱讀</h3>${chapters([s.chapter])}<p>${s.question}</p>`+(currentYear==='1943'?`<p>${link('https://history.state.gov/historicaldocuments/frus1943CairoTehran/comp2','美國國務院會議文獻')}</p>`:'')]}const entries={book:['THE BOOK / 閱讀這部傳記','從人物經歷，到時代處境。',`<p>《蔣介石傳》由布賴恩·克羅澤（Brian Crozier）撰寫，封長虹翻譯。本頁對應國際文化出版公司 2014 年精裝版本，ISBN 9787512506848。封面與版本信息依據書目頁面覈對。</p><h3>二十四章怎樣組織一生？</h3><p>目錄從「保守的革命者」開始，經過求學日本、北伐、婚姻、抗戰與盟國關係，再轉向戰後局勢、失去大陸與晚年，最後進入人物評價。這樣的結構把私人經歷、軍事活動和政治決策放在連續敘事中。</p>${photoBlock('whampoa')}<h3>本書的材料與視角</h3><p>出版方介紹強調作者收集文獻並採訪當事人。訪談能夠補充人物細節，但回憶與解釋也有各自的立場。閱讀時，可以留意事實記述、當事人的說法和作者的判斷之間的區別。</p><p>澳大利亞戰爭紀念館書目記錄了 1976 年英文原著 <em>The Man Who Lost China</em>，署名 Brian Crozier with Eric Chou。原著的出版時間與本頁中文精裝版時間不同。</p><p>${link(sourceBook,'對應中文版本書目')} · ${link('https://www.awm.gov.au/collection/LIB30598','英文原著館藏記錄')}</p>`],rise:['READING PATH / 01','走向歷史的中心。',`${photoBlock('whampoa')}<p>一個人怎樣從求學、軍事訓練與革命活動，進入更大的政治舞臺？這一組章節提供了觀察成長、組織關係與軍事行動的路線。</p>${chapters([3,5,6,7,8,9,10])}<h3>帶着問題閱讀</h3><p>軍事組織如何與政治權力相互作用？孫中山的影響、早期合作與後來分歧，在人物道路中分別佔據怎樣的位置？</p>`],war:['READING PATH / 02','在戰爭中，作出選擇。',`${photoBlock('cairo')}<p>從西安事變到全面抗戰，再到與盟國的合作，本書把個人決策放入戰爭壓力與國際關係中。可以將這些章節和開羅會議公開檔案對照閱讀。</p>${chapters([14,15,16,17,18])}<h3>帶着問題閱讀</h3><p>軍事壓力、政治關係與外交資源，怎樣共同影響選擇？同盟內部出現不同判斷時，合作如何維持？</p>`],turn:['READING PATH / 03','轉折之後，如何理解？',`${photoBlock('chongqing')}<p>抗戰勝利並沒有結束政治衝突。目錄從戰後調停轉向引退、失去大陸與晚年，將結局、延續與評價連接起來。</p>${chapters([19,20,21,22,23,24])}<h3>帶着問題閱讀</h3><p>作者如何解釋失去大陸？哪些解釋依賴人物性格，哪些涉及制度、軍事與社會環境？讀到最後一章時，可以回到前面的敘事重新檢視。</p>`],contents:['CONTENTS / 24 CHAPTERS','從目錄，選擇你的入口。',chapters(Array.from({length:24},(_,i)=>i+1))+'<p>後記</p><p>以上爲書目中列出的章節名稱；本站導讀爲原創概括，非書中原文。</p><p>'+link(sourceBook,'覈對精裝版目錄')+'</p>'],perspective:['THE AUTHOR / 閱讀視角','理解作者，也保留自己的判斷。',`<p>布賴恩·克羅澤是一位記者與作家，曾爲路透社、《經濟學人》等機構工作，也長期關注冷戰時期的政治與國際事務。這些經歷構成了他觀察人物和政治的背景。</p><p>1976 年《Kirkus Reviews》對英文原著的評論認爲，書中對人物本身的瞭解，比對其失去中國大陸的解釋更有說服力。這是一家評論機構的評價，不能代替讀者對原書的判斷。</p><h3>可以怎樣讀？</h3><p>把作者觀點、當事人回憶與可以覈查的事件分開看；對關鍵事件查閱不同來源。本站使用「一生，不止一種答案」作爲閱讀邀請，不以宣傳文案代替歷史結論。</p><p>${link('https://www.thebaron.info/news/article/2012/08/07/obituary-brian-crozier','作者生平')} · ${link('https://www.kirkusreviews.com/book-reviews/a/brian-crozier/the-man-who-lost-china-the-first-full-biography/','英文原著書評')}</p>`],sources:['SOURCES / 可查證的閱讀','內容、影像與創作來源。',`<h3>書籍與歷史內容</h3><ul class="source-list"><li>${link(sourceBook,'三民書目：2014 精裝版、封面、目錄')}</li><li>${link('https://www.awm.gov.au/collection/LIB30598','澳大利亞戰爭紀念館：1976 英文原著')}</li><li>${link('https://history.state.gov/historicaldocuments/frus1943CairoTehran/comp2','美國國務院：開羅會議文獻')}</li><li>${link('https://fdr.blogs.archives.gov/2012/11/20/found-in-the-archives-48/','羅斯福總統圖書館：開羅會議檔案介紹')}</li></ul><h3>歷史照片</h3><p>歷史照片均附原始檔案鏈接；不表示照片出自本書內頁。以下 Commons 文件頁面標註公共領域，具體署名與說明見各原頁。</p><ul class="source-list">${Object.values(photos).map(p=>`<li>${link(p.source,p.title)}<p>${p.description}</p></li>`).join('')}</ul><h3>原創視覺</h3><p>首頁墨線人物爲依據歷史肖像創作的插畫，非歷史照片。頁面視覺研究參考 Persona 5 Royal 的斜切版式、剪紙文字、黑白層次與快速切入節奏；本站爲獨立書籍介紹頁。字體使用 Noto Sans CJK（OFL）與 Anton（OFL）。</p>`]};return entries[key]}
$$('[data-reader]').forEach(b=>b.onclick=()=>{const d=readerData(b.dataset.reader);$('#reader-label').textContent=d[0];$('#reader-title').textContent=d[1];$('#reader-content').innerHTML=d[2];openDialog('reader')});
function impact(el){if(reduced.matches||!el.animate)return;const base=getComputedStyle(el).transform;el.animate([{transform:'translate(-28px,18px) rotate(-9deg) scale(.78)',opacity:0},{transform:base==='none'?'none':base,opacity:1}],{duration:470,easing:'cubic-bezier(.12,.8,.22,1.15)',fill:'none'})}
if(!reduced.matches){$$('.title-character').forEach((el,i)=>setTimeout(()=>impact(el),120+i*75));const targets=$$('.chapter-tag,.about-grid,.book-features,.life-heading,.life-panel,.world-title,.cairo-photo,.world-story,.relation-top,.relation-layout,.chapter-heading,.chapter-card,.edition-layout');targets.forEach(el=>el.classList.add('reveal-block'));const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');$$('.impact-heading>span,.impact-heading>strong',e.target).forEach((x,i)=>setTimeout(()=>impact(x),i*80));io.unobserve(e.target)}}),{threshold:.08});targets.forEach(el=>io.observe(el))}
let scheduled=false;const cursor=$('.cursor-star');function scrollUpdate(){scheduled=false;const max=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.transform=`scaleX(${max?scrollY/max:0})`;if(!reduced.matches&&scrollY<innerHeight*1.3)$('.hero-figure').style.translate=`0 ${Math.min(scrollY*.10,90)}px`}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(scrollUpdate)}},{passive:true});addEventListener('resize',scrollUpdate);scrollUpdate();
if(matchMedia('(pointer:fine)').matches&&!reduced.matches){addEventListener('pointermove',e=>{cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';cursor.style.opacity=e.target.closest('a,button')?'.85':'0'});document.addEventListener('pointerleave',()=>cursor.style.opacity='0')}
document.addEventListener('click',e=>{if(e.target.closest('a')&&!e.target.closest('[data-menu]'))beep()});
// Shape headings as individual cutouts; preserve the full accessible text.
$$('.impact-heading>span,.impact-heading>strong,.card-title>strong').forEach(el=>{const owner=el.closest('h2,button');if(owner&&!owner.hasAttribute('aria-label'))owner.setAttribute('aria-label',owner.textContent.replace(/\s+/g,' ').trim());el.setAttribute('aria-hidden','true');const nodes=[...el.childNodes];nodes.forEach(node=>{if(node.nodeType!==Node.TEXT_NODE)return;const f=document.createDocumentFragment();[...node.textContent].forEach((char,i)=>{if(/\s/.test(char)){f.append(document.createTextNode(char));return}const s=document.createElement('span');s.className='cut-letter';s.textContent=char;s.setAttribute('aria-hidden','true');s.style.setProperty('--tilt',[-5,4,-2,6,-4,2][i%6]+'deg');s.style.setProperty('--offset',[0,-1,2,-2][i%4]+'px');s.style.setProperty('--stretch',[1.07,.98,1.11,1.02][i%4]);f.append(s)});node.replaceWith(f)})});
// Letter impacts are replayed on re-entry, with sharp overshoot then a readable rest.
function slamLetters(el){if(reduced.matches)return;const letters=$$('.cut-letter',el);letters.forEach((letter,i)=>{const rest=getComputedStyle(letter).transform;letter.animate([{transform:'translate(45px,-35px) rotate(22deg) scale(1.45)',opacity:0},{transform:'translate(-4px,3px) rotate(-4deg) scale(.98)',opacity:1,offset:.75},{transform:rest,opacity:1}],{duration:510,delay:i*26,easing:'cubic-bezier(.13,.85,.2,1)',fill:'none'})})}
const slamObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting&&!e.target.dataset.inFrame){e.target.dataset.inFrame='1';slamLetters(e.target)}else if(!e.isIntersecting)delete e.target.dataset.inFrame}),{threshold:.45});$$('.impact-heading,.card-title').forEach(el=>slamObserver.observe(el));
menuLinks.forEach((a,i)=>a.style.setProperty('--order',i));
function slashCut(){if(reduced.matches)return;const el=document.createElement('div');el.className='motion-cut';el.setAttribute('aria-hidden','true');document.body.append(el);setTimeout(()=>el.remove(),460)}
$$('[data-reader],#menu-toggle,[data-year],[data-relation]').forEach(b=>b.addEventListener('click',slashCut));
if(!reduced.matches){document.fonts.ready.then(()=>{$$('.title-character').forEach((el,i)=>{const rest=getComputedStyle(el).transform;el.animate([{transform:'translate(-100px,70px) rotate(-35deg) scale(2.1)',opacity:0},{transform:'translate(9px,-5px) rotate(3deg) scale(1.03)',opacity:1,offset:.72},{transform:rest,opacity:1}],{duration:750,delay:i*95,easing:'cubic-bezier(.1,.85,.2,1)'})});$('.hero-figure').animate([{opacity:0,translate:'180px 50px'},{opacity:1,translate:'0 0'}],{duration:850,easing:'cubic-bezier(.1,.85,.2,1)',delay:150})})}
